  c.add('BR-1', 3);
  c.remove('BR-1', 1);
  assert.equal(c.lines()[0].qty, 2);
  c.remove('BR-1');
  assert.deepEqual(c.lines(), []);
  assert.throws(() => c.remove('BR-1'), Error);
});

