	b := hBook()
	n := len(b.Entries())
	_, err := b.Post(-1, "x")
	hIs(t, "negative day comes first", err, ErrBadDay)
	_, err = b.Post(1, "x")
	hIs(t, "no lines", err, ErrTooFew)
	_, err = b.Post(1, "x", hLn("assets:cash", 5))
	hIs(t, "one line", err, ErrTooFew)
