"""Plain data classes of the ferry desk."""
from dataclasses import dataclass
from datetime import date


@dataclass(frozen=True)
class Passenger:
    name: str
    age: int


@dataclass(frozen=True)
class Vehicle:
    kind: str  # car, van, bike, camper
    length_cm: int


@dataclass
class Sailing:
    id: str
    route: str
    day: date
    seats: int
    deck_cm: int


@dataclass
class Booking:
    id: str
    sailing_id: str
    passengers: tuple
    vehicle: object  # Vehicle or None
    fare_cents: int
    status: str = "confirmed"

